  &DefaultButton;




function dir$dmrmail(p){
  this.constructor(p);
}
dir$dmrmail.prototype = new DirEvent();
dir$dmrmail.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmrmail.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid();

	p.request('request_ma_rmail', '', '' , function(pp, d, run){
		if (run) {
			p.setDisabled('ma_rmail', true);
		}
	});

  dir$dmrmailDisabledMasterField(p, g);

}

function dir$dmrmailDisabledMasterField(p, g){

  if(p.valForm('ma_rmail').trim() != '')
  {
    p.setDisabled('ma_rmail', true);
  }
  else
  {
    p.setDisabled('ma_rmail', false);
  }
}







		.control-label.r_mail, .control-label.ten_mail
		{	
			//font-weight:bold;	
			color: #499b98;;
		}







						SELECT 
							CASE 
								WHEN MAX(ma_rmail) IS NULL THEN 'RM001'
								ELSE 'RM' + RIGHT('00' + CAST(CAST(SUBSTRING(MAX(ma_rmail), 3, LEN(MAX(ma_rmail))) AS INT) + 1 AS VARCHAR), 3)
							END AS [!ma_rmail]
						FROM dmrmail






		SELECT ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS row_num, * INTO #temp_d FROM #data;

		DECLARE @i int, @ci int, @next_num int;
		SET @i = 1

		SELECT @ci = MAX(row_num) FROM #temp_d
		SELECT @next_num = ISNULL(CAST(SUBSTRING(MAX(ma_rmail), 3, LEN(MAX(ma_rmail))-2) AS INT) + 1, 1) 
		FROM dmrmail 
		WHERE ma_rmail LIKE 'RM%';

		WHILE @i <= @ci
		BEGIN
		    DECLARE @current_r_mail varchar(255);
			SELECT @current_r_mail = r_mail FROM #temp_d WHERE row_num = @i;

			UPDATE #data 
			SET ma_rmail = 'RM' + RIGHT('000000' + CAST(@next_num AS VARCHAR(6)), 6)
			WHERE r_mail = @current_r_mail;

			SET @i = @i + 1
			SET @next_num = @next_num + 1;
		END

		UPDATE #data set unit_id = 1, so_lan_gui = 0, lastsentdate = null;

		@@insert
